### 5. Translation Layer & Adapter Architecture

**File:** [/Users/dwahl/Scripts/pantoken/docs/.vitepress/i18n.ts](docs/.vitepress/i18n.ts) (~400 lines)

**Symmetric prefix swap (lines 1–50):**
```typescript
import { LOCALES } from "@pantoken/web-components";

export type DocsLocale = string;

/**
 * Every locale the docs site builds: `root` (English) plus every non-`en` locale from
 * `@pantoken/web-components`'s `LOCALES` (44 BCP47 tags — `en` is dropped since `root` already covers
 * US English).
 */
export const NON_ROOT_LOCALES = Object.keys(LOCALES).filter((key) => key !== "en");

export const parseRequestedLocales = (
  requested: string | undefined,
  fallback: readonly string[],
): readonly string[] => {
  // Supports: "hu", "primary", "secondary", "primary,-hu" (subtract), "-ga" (all but Irish)
  const entries = (requested ?? "").split(/[,\s]+/).filter((entry) => entry.length > 0);
  if (entries.length === 0) return fallback;
  // [… expands tiers to concrete locale lists, validates against LOCALES …]
};
```

**UI strings and resolution (lines 60–150):**
```typescript
export interface UiStrings {
  description: string;
  nav: { guide: string; css: string; api: string };
  sidebar: { intro: string; guides: string; /* … */ };
  editText: string;
  themeSelector: { label: string; rebrand: string; canvas: string; /* … */ };
  cdnPicker: CdnPickerStrings;
  getStartedTabs: GetStartedTabsStrings;
  chrome: { outlineLabel: string; docFooterPrev: string; /* … */ };
  search: { buttonText: string; displayDetails: string; /* … */ };
}

const sourceUiStrings = Object.fromEntries(
  Object.entries(chromeSource)  // Read from i18n.json
    .filter(([key]) => key !== "$schema")
    .map(([key, entry]) => [key, (entry as { message: string }).message]),
);

export const ENGLISH_UI_STRINGS: UiStrings = unflattenStrings(sourceUiStrings);

/**
 * Resolve the locale's `docs.chrome` PO catalog over the English defaults, so untranslated strings
 * fall back to English rather than disappearing.
 */
const uiStringsFor = (locale: DocsLocale): UiStrings => {
  if (locale === "root") return ENGLISH_UI_STRINGS;
  const config = loadConfig(new URL("../../i18n.config.json", import.meta.url).pathname);
  const resolved = resolveMessagesForLocale(config, new URL("../../", import.meta.url).pathname, "docs.chrome", locale);
  const overrides = new Map(ENGLISH_UI_LEAVES.map(({ path }) => [path, resolved.strings[path]]));
  return applyOverrides(ENGLISH_UI_STRINGS, overrides);
};

/** Per-locale metadata — route prefixes, nav/sidebar labels, and all translated UI chrome. */
export const LOCALE_THEMES: Record<DocsLocale, LocaleTheme> = new Proxy(
  {} as Record<DocsLocale, LocaleTheme>,
  {
    get: (_target, prop) => computeLocales()[prop as DocsLocale],
    // [… lazy-computed & memoized behind Proxy …]
  },
);
```

**Glossary adapter concept** (in docs/scripts/api-translation.ts, lines 150–200):
```typescript
export class GlossaryTranslationAdapter implements TranslationAdapter {
  readonly name = "glossary";
  readonly translatesProse = false;  // Never caches prose
  private readonly replacements: Array<[RegExp, string]>;

  constructor(locale = "hu") {
    const memory = TranslationMemory.load(locale, "api");
    this.replacements = GLOSSARY_TERMS.flatMap(({ kind, term }) => {
      const translated = memory.get("text", term);
      if (translated === undefined) return [];
      return [[patternFor(kind, term), replacementFor(kind, translated)] as [RegExp, string]];
    });
  }
  // [… deterministic substitution only, no prose, async wrapper for sync core …]
}
```

